//! Siemens Sinumerik's G-code, as the 840D sl and 828D read it: written by
//! the G-code renderer with this dialect's words ([`crate::render`]), and
//! read back by the G-code reader with them ([`crate::readback`]), so the
//! same checks run on it. What the two share is here: the program's name,
//! a line's words, and what custom lines may not do.
//!
//! A profile writes it with `dialect = "sinumerik"`. Its program:
//!
//! ```text
//! %_N_TOP_01_ROUGH_MPF
//! ;$PATH=/_N_MPF_DIR
//! ;generated by camcraft -- verify before running
//! G17 G40 G90 G94
//! G710
//! ;rough - adaptive - T3 G54
//! M5
//! G0 SUPA Z0 D0
//! ;6mm flat
//! T3 M6
//! D1
//! G54
//! S18000 M3
//! G0 X10 Y5
//! Z2
//! G1 Z-1 F300
//! G2 X20 Y5 I5 J0 F1200
//! ...
//! M30
//! ```
//!
//! The first two lines name the program and where it goes, as a Sinumerik
//! reads a program sent to it as text. Comments run from `;` to the line's
//! end. `G710` (`G700` in inches) sets the units of lengths and feeds both:
//! `G71` and `G70` would leave the feeds in the machine's own. Moves and
//! arcs are ISO's: `G2`/`G3` by their centre, `I`, `J` and `K` measured
//! from the arc's start, as a Sinumerik takes them unless told `=AC(..)`,
//! and a helix as an arc with its end along the plane's normal, no more
//! than half a turn a block, so no `TURN=`. A tool is changed by `T3 M6`
//! (`T="3"` with tool management, named by its number), and its length
//! and radius taken up by `D1`, its first edge; `G0 SUPA Z0 D0` takes the
//! tool to the top of Z in machine coordinates with its offsets let go,
//! and the next move in the work's takes them up again with `D1`.
//!
//! The work offsets are `G54` to `G57`, then `G505` to `G599` as far as
//! the machine has them: `G58` and `G59` are programmable offsets, which
//! add to the one selected, so a setup's offset after `G57` is `G505`.
//!
//! Holes are cycles called at each by `MCALL CYCLE81(..)`: the cycle runs
//! after each block that moves, so each hole is a block `G0 X.. Y..` with
//! both words, even where the tool is already over it, and a bare `MCALL`
//! ends the run. `CYCLE81` drills, `CYCLE82` with a pause at the bottom,
//! `CYCLE83` pecks, out of the hole between pecks or backing off to break
//! the chip, `CYCLE84` taps rigidly (its pitch's sign the thread's hand)
//! and `CYCLE840` with a floating holder. Each takes its return height
//! (`RTP`), the hole's top (`RFP`), the gap above it it feeds from
//! (`SDIS`) and its bottom (`DP`), in that order, then its own; the
//! drilling feed is the `F` in force.

use crate::custom::Concern;

/// A program's name as a Sinumerik keeps it in `%_N_<name>_MPF`: letters,
/// digits and `_`, the first two not digits, no more than 24; in capitals.
pub fn program_name(name: &str) -> String {
    let mut n: String = name
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_uppercase()
            } else {
                '_'
            }
        })
        .collect();
    if n.chars().take(2).any(|c| c.is_ascii_digit()) || n.len() < 2 {
        n = format!("P_{n}");
    }
    n.chars().take(24).collect()
}

/// A cycle called with its parameters, as `CYCLE81(20,5,2,-1.5)`: an empty
/// one, left out, is `None`.
#[derive(Debug, Clone, PartialEq)]
pub struct Call {
    /// The cycle's number: 81 for `CYCLE81`, 840 for `CYCLE840`.
    pub number: u32,
    /// Its parameters, in order.
    pub args: Vec<Option<f64>>,
}

impl Call {
    /// The `i`-th parameter, from nought, where it is given.
    pub fn arg(&self, i: usize) -> Option<f64> {
        self.args.get(i).copied().flatten()
    }
}

impl std::fmt::Display for Call {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "CYCLE{}", self.number)
    }
}

/// What a line of a Sinumerik program says: its plain words, as ISO
/// G-code's are read, and what only a Sinumerik writes.
#[derive(Debug, Clone, Default, PartialEq)]
pub(crate) struct Line {
    /// Its words, letter and number. Units as ISO's (`G710` as `G21`, `G700`
    /// as `G20`), `SUPA` and `G153` as `G53`, a pause's seconds (`G4 F2`)
    /// as a `P`, and a tool named by its number (`T="3"`) as `T3`.
    pub words: Vec<(char, f64)>,
    /// A work offset past `G57` selected: its G code's number, `505` for
    /// `G505`, as the profile has it.
    pub offset: Option<u32>,
    /// The tool's edge taken up, `D1`, or its offsets let go, `D0`.
    pub edge: Option<u32>,
    /// `MCALL`: with a cycle, called after each move from here; alone, no
    /// longer.
    pub mcall: Option<Option<Call>>,
    /// A cycle called once, here.
    pub call: Option<Call>,
}

/// The names in `line` outside its comment: runs of two letters or more,
/// as `SUPA` or `MCALL`, in capitals.
pub fn names(line: &str) -> Vec<String> {
    let code = uncommented(line);
    let mut out = Vec::new();
    let mut run = String::new();
    let mut quoted = false;
    for c in code.chars().chain(std::iter::once(' ')) {
        if c == '"' {
            quoted = !quoted;
        }
        if !quoted && (c.is_ascii_alphabetic() || c == '_') {
            run.push(c.to_ascii_uppercase());
            continue;
        }
        if run.len() > 1 {
            out.push(std::mem::take(&mut run));
        }
        run.clear();
    }
    out
}

/// `line` up to its comment, `;` outside quotes.
fn uncommented(line: &str) -> &str {
    let mut quoted = false;
    for (i, c) in line.char_indices() {
        match c {
            '"' => quoted = !quoted,
            ';' if !quoted => return line.get(..i).unwrap_or(""),
            _ => {}
        }
    }
    line
}

/// A number as a Sinumerik writes one, a sign allowed before it.
fn number(s: &str) -> Option<f64> {
    let s = s.trim();
    if s.is_empty() || !s.chars().all(|c| c.is_ascii_digit() || "+-.".contains(c)) {
        return None;
    }
    s.parse().ok()
}

/// What `line` says, or what in it is not understood. The program's first
/// line, `%_N_.._MPF`, says nothing.
pub(crate) fn line(line: &str) -> Result<Line, String> {
    let code = uncommented(line);
    let mut out = Line::default();
    if code.trim_start().starts_with('%') {
        return Ok(out);
    }
    let chars: Vec<char> = code.chars().collect();
    let mut i = 0;
    let mut mcall = false;
    while let Some(&c) = chars.get(i) {
        if c.is_whitespace() {
            i += 1;
            continue;
        }
        if !c.is_ascii_alphabetic() {
            return Err(format!("{c:?} is not part of any word"));
        }
        let start = i;
        while chars
            .get(i)
            .is_some_and(|c| c.is_ascii_alphabetic() || *c == '_')
        {
            i += 1;
        }
        let name: String = chars
            .get(start..i)
            .unwrap_or_default()
            .iter()
            .collect::<String>()
            .to_ascii_uppercase();
        // A number straight after, or after `=`.
        let mut j = i;
        let assigned = chars.get(j) == Some(&'=');
        if assigned {
            j += 1;
        }
        if assigned && name == "T" && chars.get(j) == Some(&'"') {
            let end = (j + 1..chars.len())
                .find(|&k| chars.get(k) == Some(&'"'))
                .ok_or("a tool's name is never closed")?;
            let tool: String = chars.get(j + 1..end).unwrap_or_default().iter().collect();
            let t = number(&tool)
                .filter(|t| t.fract() == 0.0 && *t >= 0.0)
                .ok_or_else(|| {
                    format!("T=\"{tool}\": a tool named other than by its number is not understood")
                })?;
            out.words.push(('T', t));
            i = end + 1;
            continue;
        }
        let digits_start = j;
        while chars
            .get(j)
            .is_some_and(|c| c.is_ascii_digit() || "+-.".contains(*c))
        {
            j += 1;
        }
        let digits: String = chars
            .get(digits_start..j)
            .unwrap_or_default()
            .iter()
            .collect();
        if name.len() > 1 {
            if name == "CYCLE" && !assigned && chars.get(j) == Some(&'(') {
                let n: u32 = digits
                    .parse()
                    .map_err(|_| format!("CYCLE{digits} is not a cycle"))?;
                let close = (j..chars.len())
                    .find(|&k| chars.get(k) == Some(&')'))
                    .ok_or_else(|| format!("CYCLE{n}( is never closed"))?;
                let inside: String = chars.get(j + 1..close).unwrap_or_default().iter().collect();
                let args = inside
                    .split(',')
                    .map(|a| {
                        let a = a.trim();
                        if a.is_empty() {
                            Ok(None)
                        } else {
                            number(a)
                                .map(Some)
                                .ok_or_else(|| format!("CYCLE{n}: {a} is not a number this reads"))
                        }
                    })
                    .collect::<Result<Vec<_>, String>>()?;
                let call = Call { number: n, args };
                if mcall {
                    out.mcall = Some(Some(call));
                } else if out.call.is_some() {
                    return Err("two cycles called in one block".into());
                } else {
                    out.call = Some(call);
                }
                i = close + 1;
                continue;
            }
            if !digits.is_empty() || assigned {
                let eq = if assigned { "=" } else { "" };
                return Err(format!("{name}{eq}{digits} is not understood"));
            }
            match name.as_str() {
                "SUPA" => out.words.push(('G', 53.0)),
                "MCALL" => {
                    if out.mcall.is_some() || mcall {
                        return Err("MCALL twice in one block".into());
                    }
                    mcall = true;
                    out.mcall = Some(None);
                }
                other => return Err(format!("{other} is not understood")),
            }
            i = j;
            continue;
        }
        let letter = name.chars().next().unwrap_or(' ');
        let v = number(&digits).ok_or_else(|| {
            if assigned {
                format!("{letter}= with other than a number after it is not understood")
            } else {
                format!("{letter}{digits} is not a word")
            }
        })?;
        i = j;
        match letter {
            'D' => {
                if out.edge.is_some() {
                    return Err("D appears twice".into());
                }
                if v.fract() != 0.0 || v < 0.0 {
                    return Err(format!("D{v} is not an edge"));
                }
                #[allow(clippy::cast_possible_truncation, clippy::cast_sign_loss)]
                {
                    out.edge = Some(v as u32);
                }
            }
            'G' => {
                #[allow(clippy::cast_possible_truncation)]
                let code = (v.fract() == 0.0).then_some(v as i64);
                match code {
                    Some(710) => out.words.push(('G', 21.0)),
                    Some(700) => out.words.push(('G', 20.0)),
                    Some(n @ (70 | 71)) => {
                        return Err(format!(
                            "G{n} converts lengths but not feeds: G700 or G710 is understood"
                        ));
                    }
                    Some(153) => out.words.push(('G', 53.0)),
                    Some(500) => {
                        return Err("G500 lets the work offset go: not understood".into());
                    }
                    Some(n @ (58 | 59 | 505..=599)) => {
                        if out.offset.is_some() {
                            return Err("two work offsets in one block".into());
                        }
                        out.offset = u32::try_from(n).ok();
                    }
                    _ => out.words.push(('G', v)),
                }
            }
            letter => out.words.push((letter.to_ascii_uppercase(), v)),
        }
    }
    if mcall && out.words.iter().any(|(c, _)| "XYZABCIJK".contains(*c)) {
        return Err("MCALL with a move in its block is not understood".into());
    }
    // A pause's time is its F, which is no feed.
    if out
        .words
        .iter()
        .any(|&(c, v)| c == 'G' && (v - 4.0).abs() < 1e-9)
    {
        for w in &mut out.words {
            if w.0 == 'F' {
                w.0 = 'P';
            }
        }
    }
    Ok(out)
}

/// What is wrong with a line of custom code for a Sinumerik, if anything:
/// what moves the machine or changes how the rest is read is refused, as
/// custom G-code's is ([`crate::custom::concern`]), with a Sinumerik's own
/// words for it (a cycle, `MCALL`, `SUPA`, a frame such as `TRANS` or
/// `ROT`, a jump, `X=..`); a name that is no word of its own, a subprogram
/// called, is not read, and warned about. `MSG(..)` and `STOPRE` are let
/// through.
pub fn concern(line: &str) -> Option<Concern> {
    // ISO's words first: an axis, a G code but G4, M6, M30 and the like.
    let code = uncommented(line);
    let without_quotes: String = {
        let mut quoted = false;
        code.chars()
            .filter(|c| {
                if *c == '"' {
                    quoted = !quoted;
                    return false;
                }
                !quoted
            })
            .collect()
    };
    let iso = crate::custom::concern(&without_quotes.replace(['(', ')'], " "));
    if let Some(Concern::Refused(_)) = iso {
        return iso;
    }
    // An axis given by `=`, as `X=10` or `Z=R1`.
    let chars: Vec<char> = without_quotes.chars().collect();
    for (k, c) in chars.iter().enumerate() {
        let alone = k == 0 || chars.get(k - 1).is_none_or(|p| !p.is_ascii_alphanumeric());
        if alone && "XYZABCUVW".contains(c.to_ascii_uppercase()) && chars.get(k + 1) == Some(&'=') {
            return Some(Concern::Refused(format!(
                "{c}= moves the machine: custom code may not move it"
            )));
        }
    }
    let mut unread = None;
    // `L100` calls subprogram 100.
    if let Some(call) = crate::custom::words(&without_quotes)
        .into_iter()
        .find(|(c, _, _)| *c == 'L')
    {
        unread = Some(call.2);
    }
    for name in names(&without_quotes) {
        let refused = |why: &str| Some(Concern::Refused(format!("{name} {why}")));
        match name.as_str() {
            "MSG" | "STOPRE" => {}
            "MCALL" | "SUPA" | "POS" | "POSA" | "SPOS" | "CIP" | "CT" | "CR" | "TURN" | "AC"
            | "IC" | "DC" | "ACP" | "ACN" | "AP" | "RP" => {
                return refused("moves the machine: custom code may not move it");
            }
            "TRANS" | "ATRANS" | "ROT" | "AROT" | "ROTS" | "AROTS" | "SCALE" | "ASCALE"
            | "MIRROR" | "AMIRROR" | "TRAORI" | "TRAFOOF" | "TRACYL" | "TRANSMIT" | "TOFRAME"
            | "TCOABS" | "PAROT" | "CORROF" => {
                return refused(
                    "changes the frame the program is read in: custom code may not change it",
                );
            }
            "GOTO" | "GOTOF" | "GOTOB" | "GOTOC" | "RET" | "REPEAT" | "REPEATB" | "LABEL" => {
                return refused("jumps, so the program is read some other way");
            }
            n if n.starts_with("CYCLE") => {
                return refused("is a cycle, which moves the machine");
            }
            _ => {
                unread.get_or_insert(name);
            }
        }
    }
    if let Some(name) = unread {
        return Some(Concern::Unread(format!(
            "{name} calls something that is not read: what it does is not checked"
        )));
    }
    iso
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::panic, clippy::float_cmp)]
mod tests {
    use super::*;

    #[test]
    fn a_name_is_kept_as_a_sinumerik_keeps_it() {
        assert_eq!(program_name("top-01 rough"), "TOP_01_ROUGH");
        assert_eq!(program_name("1001"), "P_1001");
        assert_eq!(program_name(""), "P_");
        assert_eq!(program_name(&"a".repeat(40)).len(), 24);
    }

    #[test]
    fn a_line_is_read_into_its_words() {
        let l = line("N10 G0 SUPA Z0 D0 ;up").unwrap();
        assert_eq!(
            l.words,
            vec![('N', 10.0), ('G', 0.0), ('G', 53.0), ('Z', 0.0)]
        );
        assert_eq!(l.edge, Some(0));
        let l = line("T=\"3\" M6").unwrap();
        assert_eq!(l.words, vec![('T', 3.0), ('M', 6.0)]);
        assert!(line("T=\"drill 6\"").unwrap_err().contains("named"));
        let l = line("MCALL CYCLE83(20,5,2,-1.5,,3,,0,0,0,1,0,,,0.25)").unwrap();
        let call = l.mcall.unwrap().unwrap();
        assert_eq!(call.number, 83);
        assert_eq!(call.arg(3), Some(-1.5));
        assert_eq!(call.arg(4), None);
        assert_eq!(call.arg(14), Some(0.25));
        assert_eq!(line("MCALL").unwrap().mcall, Some(None));
        assert_eq!(line("G505").unwrap().offset, Some(505));
        assert_eq!(line("G4 F1.5").unwrap().words, vec![('G', 4.0), ('P', 1.5)]);
        assert_eq!(line("G710").unwrap().words, vec![('G', 21.0)]);
        assert_eq!(line("%_N_GOLDEN_MPF").unwrap(), Line::default());
        for bad in ["G71", "G2 X1 Y1 I=AC(5) J0", "TURN=2", "TRANS X10", "G500"] {
            assert!(line(bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn custom_lines_may_not_move_the_machine() {
        for ok in [
            "MSG(\"check the clamps\")",
            "M0",
            "G4 F2",
            "M7 ;air",
            "STOPRE",
        ] {
            assert_eq!(concern(ok), None, "{ok}");
        }
        for refused in [
            "X=10",
            "G0 X10",
            "TRANS Z5",
            "MCALL CYCLE81(10,0,2,-5)",
            "CYCLE800()",
            "G0 SUPA Z0",
            "GOTOF END",
            "M30",
        ] {
            assert!(
                matches!(concern(refused), Some(Concern::Refused(_))),
                "{refused}: {:?}",
                concern(refused)
            );
        }
        assert!(matches!(concern("L100"), Some(Concern::Unread(_))));
        assert!(matches!(concern("MY_PROBE"), Some(Concern::Unread(_))));
    }
}
